sp_MovimentarEstoque	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_MovimentarEstoque`(\n\n    p_produto_id       INT,\n\n    p_idEmpresa        INT,\n\n    p_tipoMovimentacao VARCHAR(20),\n\n    p_Qtde             INT,\n\n    p_Observacao       VARCHAR(300),\n\n    p_usuario_id       INT\n\n)\nBEGIN\n\n    DECLARE v_estoque_id INT;\n\n    DECLARE v_tipo_id    INT;\n\n    DECLARE v_qtde_atual INT;\n\n\n\n    SELECT idTipoMovimentacao INTO v_tipo_id\n\n    FROM TipoMovimentacao\n\n    WHERE Nome = p_tipoMovimentacao\n\n    LIMIT 1;\n\n\n\n    SELECT idEstoque, QtdeAtual INTO v_estoque_id, v_qtde_atual\n\n    FROM Estoque\n\n    WHERE produto_id = p_produto_id AND idEmpresa = p_idEmpresa\n\n    LIMIT 1;\n\n\n\n    IF p_tipoMovimentacao = 'ENTRADA' THEN\n\n        UPDATE Estoque\n\n        SET QtdeAtual = QtdeAtual + p_Qtde, dthAtualizacao = CURDATE()\n\n        WHERE idEstoque = v_estoque_id;\n\n\n\n    ELSEIF p_tipoMovimentacao = 'AJUSTE' THEN\n\n        UPDATE Estoque\n\n        SET QtdeAtual = p_Qtde, dthAtualizacao = CURDATE()\n\n        WHERE idEstoque = v_estoque_id;\n\n\n\n    ELSE\n\n        UPDATE Estoque\n\n        SET QtdeAtual = GREATEST(QtdeAtual - p_Qtde, 0), dthAtualizacao = CURDATE()\n\n        WHERE idEstoque = v_estoque_id;\n\n    END IF;\n\n\n\n    INSERT INTO MovimentacaoEstoque (\n\n        estoque_id, usuario_id, tipoMovimentacao_id,\n\n        produto_id, dthMovimentacao, Qtde, Observacao, idEmpresa\n\n    ) VALUES (\n\n        v_estoque_id, p_usuario_id, v_tipo_id,\n\n        p_produto_id, CURDATE(), p_Qtde, p_Observacao, p_idEmpresa\n\n    );\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
